bool GetPlatformManualSignature(FName Feature,TArray<FName>& Names,TArray<EDivineBeastsDemoParameterType>& Types,TArray<FName>& Operations)
{
    for(const auto& S:Signatures())if(S.Feature==Feature){Names=S.Names;Types=S.Types;Operations=S.Operations;return true;}
    Names.Reset();Types.Reset();Operations.Reset();return false;
}
bool ValidatePlatformManualContract(const FDivineBeastsDemoScenarioDefinition& Scenario)
{
    TArray<FName> Names,Operations;TArray<EDivineBeastsDemoParameterType> Types;
    if(!GetPlatformManualSignature(Scenario.FeatureId,Names,Types,Operations) || Scenario.Parameters.Num()!=Names.Num() || Scenario.Operations.IsEmpty())return false;
    for(int32 I=0;I<Names.Num();++I)if(Scenario.Parameters[I].ParameterId!=Names[I] || Scenario.Parameters[I].DefaultValue.Type!=Types[I])return false;
    for(FName Op:Scenario.Operations)if(!Operations.Contains(Op))return false;
    return true;
}
