class FManualRequirementMissing final : public FPlatformManualBase
{
public:FManualRequirementMissing(UWorld& W,FName F):FPlatformManualBase(W,F){}
private:
    FGamePlatformResult PrepareService() override
    {return ManualError(TEXT("Demo.ProgressionProviderImplementationMissing"),TEXT("当前源码只有IGamePlatformProgressionSnapshotProvider抽象合同；没有实际Provider实现和受控定位入口，不能伪造资格满足。"));}
    void ExecuteService(FName,const FManualArguments&,FDivineBeastsDemoOperationCompletion Done) override
    {Done(Context.Token,ManualError(TEXT("Demo.ProgressionProviderMissing"),TEXT("真实成长资格Provider未准备。")));}
};
