TArray<FDivineBeastsDemoAdapterRegistrationHandle> RegisterPlatformServiceScenarios(UDivineBeastsDemoCatalogSubsystem& Catalog)
{
    TArray<FDivineBeastsDemoAdapterRegistrationHandle> Handles;
    for(const auto& Signature:Signatures())
    {
        const FName Feature=Signature.Feature;
        const FName Adapter(*(FString(TEXT("PlatformServices."))+Feature.ToString()));
        const auto Handle=Catalog.RegisterScenarioAdapter(Adapter,[Feature](UWorld& W){return CreatePlatformServiceScenario(W,Feature);});
        if(!Handle.IsValid()){for(const auto& Own:Handles)Catalog.UnregisterScenarioAdapter(Own);return {};}
        Handles.Add(Handle);
    }
    return Handles;
}
